    this.health = 100;
    this.maxHealth = 100;
    this.destroyed = false;
    this.exploded = false;
    this.smokeClock = 0;
    this.vx = 0;
    this.vy = 0;
    this.steer = 0;
    this.drift = false;
    this.driver = null;
