    this.steer = steer;
    this.drift = handbrake && speedRatio > 0.18;
    const reverse = this.speed < -2 ? -1 : 1;
    this.heading = wrapAngle(this.heading + steer * reverse * (0.35 + speedRatio * 1.75) * dt);
