      } else {
        car.health = Math.max(0, car.health - 6);
        car.speed *= 0.45;
      }
      hazard.hit = true;
      if (car.health <= 0) car.explode(this.game.effects, this.game.wantedSystem);
    }
    this.hazards = this.hazards.filter((hazard) => !hazard.hit);
  }

